/*
 * A044139  Numbers n such that string 0,1 occurs in the base 7 representation
 *          of n but not of n-1.
 * https://oeis.org/A044139
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the smallest positive integer m such that the string “01”
 *            occurs in the base‑7 expansion of m but does **not** occur in
 *            the base‑7 expansion of m‑1. The sequence is generated by a
 *            simple scan of the natural numbers
 * Range:     u8 n <= 5, u16 n <= 42, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   has01_base7
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function may be called in any order; it remembers all
   terms it has already computed.  It is efficient enough for
   n up to about 10 000. */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>   /* for size_t */
#include "../utils/has01_base7.h"

static seq_t *cache = NULL;        /* array of found terms */
static size_t cache_cap = 0;       /* current capacity */
static size_t cache_cnt = 0;       /* number of terms stored */

static seq_t next_candidate = 1;   /* next integer to test */

/* Grow the cache array to at least min_cap elements. */
static void grow_cache(size_t min_cap)
{
    if (min_cap <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    if (new_cap < min_cap)
        new_cap = min_cap;
    seq_t *new_ptr = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    if (!new_ptr)
        abort();          /* memory allocation failure */
    cache = new_ptr;
    cache_cap = new_cap;
}

/* Return the n-th term of the sequence (a(1) is the first term). */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;   /* undefined for n == 0, but return 0 safely */

    while (cache_cnt < (size_t)n) {
        seq_t m = next_candidate;
        bool cur_has = has01_base7(m);
        bool prev_has = has01_base7(m - 1);
        if (cur_has && !prev_has) {
            grow_cache(cache_cnt + 1);
            cache[cache_cnt++] = m;
        }
        next_candidate++;
    }
    return cache[(size_t)n - 1];
}
